import {api,esc} from './config.mjs';
import {suggestCity} from './location.mjs';
export const cinemaSlides=[
 {image:'/assets/cinema/community-art.webp',alt:'Ilustração dos Figurantes reunidos diante da cidade',label:'Nossa comunidade',position:'65% center'},
 {image:'/assets/cinema/live-art.webp',alt:'Ilustração de um apresentador de costas e um Figurante em ambiente de gravação',label:'A conversa continua',position:'65% center'},
 {image:'/assets/cinema/hero.webp',alt:'Balanço vazio diante de uma escola ao entardecer',label:'O começo',position:'center'},
 {image:'/assets/cinema/hospital.webp',alt:'Leito hospitalar vazio em preto e branco',label:'Um instante',position:'center 48%'},
 {image:'/assets/cinema/street.webp',alt:'Rua de bairro brasileiro ao pôr do sol',label:'Os caminhos',position:'center'},
 {image:'/assets/cinema/football.webp',alt:'Campo de futebol ao entardecer',label:'As lembranças',position:'center'},
 {image:'/assets/cinema/schoolyard.webp',alt:'Pátio escolar',label:'As origens',position:'center'}
];
const play='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 4 12 8-12 8z"/></svg>';
export const cinemaHomeMarkup=()=>`<div class="cinema-home"><div id="founder-notice" class="founder-notice" hidden></div><section class="cinema-hero" aria-label="HOCCO — carrossel da série documental" aria-roledescription="carrossel" tabindex="0"><div class="cinema-frames">${cinemaSlides.map((s,i)=>`<img class="cinema-frame ${i===0?'is-current':''}" src="${s.image}" alt="${esc(s.alt)}" style="object-position:${s.position}" ${i===0?'fetchpriority="high"':'loading="lazy"'}>`).join('')}</div><div class="cinema-shade" aria-hidden="true"></div><span class="cinema-frame-art-label">Imagens ilustrativas · universo HOCCO</span><button class="cinema-arrow cinema-prev" type="button" aria-label="Imagem anterior">‹</button><div class="cinema-copy"><span class="cinema-coming"><i></i>Em breve</span><h1>HOCCO<span>.</span></h1><p class="cinema-part">Parte 1</p><p class="cinema-tagline">Você chegou no meio da história.</p><p class="cinema-original">Uma série original DOOX Studios</p><div class="cinema-actions"><a class="cinema-primary" href="#assistir">${play}Assistir à HOCCO</a><button class="cinema-secondary" id="cinema-participate" type="button">Participar do reality</button></div></div><button class="cinema-arrow cinema-next" type="button" aria-label="Próxima imagem">›</button><div class="cinema-controls"><div class="cinema-sound"><button id="cinema-sound" type="button" aria-label="Ativar trilha da HOCCO" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 4 5 9H2v6h3l6 5V4ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/></svg><span>Ativar trilha da HOCCO</span></button><span class="sound-wave" aria-hidden="true">${Array.from({length:15},(_,i)=>`<i style="--bar:${[25,45,70,100,60,85,40][i%7]}%"></i>`).join('')}</span><label class="sound-volume"><span class="sr-only">Volume da trilha</span><input id="cinema-volume" type="range" min="0" max="1" step="0.05" value="0.3" aria-label="Volume da trilha"></label></div><div class="cinema-progress" aria-label="Escolher imagem">${cinemaSlides.map((s,i)=>`<button type="button" data-cinema-slide="${i}" aria-label="${i+1}. ${s.label}" aria-current="${i===0}"><span></span></button>`).join('')}</div><div class="cinema-thumbnails">${cinemaSlides.slice(0,3).map((s,i)=>`<button type="button" data-cinema-slide="${i}" aria-label="Ver ${s.label}"><img src="${s.image}" alt="" loading="lazy"></button>`).join('')}</div><button class="cinema-motion" id="cinema-motion" type="button" aria-label="Pausar carrossel">Ⅱ</button></div></section><nav class="cinema-tabs" aria-label="Sobre a série"><button class="is-active" data-cinema-tab="sinopse" aria-pressed="true">Sinopse</button><button data-cinema-tab="episodios" aria-pressed="false">Episódios</button><button data-cinema-tab="projetos" aria-pressed="false">Projetos</button></nav><section class="cinema-editorial" id="cinema-editorial" aria-live="polite" hidden></section><div class="cinema-social-grid"><section class="cinema-live-card"><div id="home-programming" aria-live="polite"><h2>A conversa continua <span class="cinema-live-badge">LIVE</span></h2><p>Consultando a próxima conversa com a comunidade…</p></div></section><section class="community-section cinema-community" id="community-section" aria-labelledby="community-title"><div class="community-heading"><h2 id="community-title">Comunidade HOCCO<span>.</span></h2><a class="home-view-all" href="#comunidade">Ver todas →</a></div><div class="community-carousel" id="community-carousel"><div class="community-track" id="community-track" aria-live="polite"><div class="community-empty">Carregando mensagens da Comunidade…</div></div></div><button class="cinema-message-button" id="community-send" type="button">Enviar mensagem <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/></svg></button></section></div><section class="cinema-sponsors" id="cinema-sponsors"><div class="cinema-section-heading"><h2>Ofertas na sua cidade</h2><a href="/ir-alem/">Explorar empresas →</a></div><div id="cinema-sponsor-content"><p class="hint">Buscando as marcas que fortalecem a HOCCO…</p></div></section><details class="cinema-live-queue" id="live-queue"><summary>Fila de participação na LIVE <span>Ver mensagens</span></summary><div id="live-queue-list"><p>Carregando fila…</p></div></details><div class="cinema-bottom-actions"><a href="#enviar">Sua mensagem no vídeo oficial →</a><a href="/cliente/#acompanhar">Acompanhar meu pedido →</a><a href="/ir-alem/#novo">Apresentar minha empresa →</a><span id="cinema-install-slot"></span></div></div>`;
let soundtrack;
export function mountCinema(root,{participate,notify=()=>{},reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches}={}){
 const hero=root.querySelector('.cinema-hero');if(!hero)return()=>{};
 let index=0,paused=reducedMotion(),timer,disposed=false,touchStart=null;
 const audio=soundtrack||(soundtrack=new Audio('/assets/cinema/hocco-theme.mp3'));audio.loop=true;audio.preload='none';audio.volume=.3;
 const sound=root.querySelector('#cinema-sound'),motion=root.querySelector('#cinema-motion');
 const paintSound=()=>{const playing=!audio.paused;sound.setAttribute('aria-pressed',String(playing));sound.setAttribute('aria-label',playing?'Pausar trilha da HOCCO':'Ativar trilha da HOCCO');sound.querySelector('span').textContent=playing?'Trilha da HOCCO':'Ativar trilha da HOCCO';hero.classList.toggle('sound-playing',playing)};
 const stop=()=>{clearTimeout(timer);timer=null};
 const schedule=()=>{stop();if(!paused&&!document.hidden&&!disposed)timer=setTimeout(()=>{select(index+1);schedule()},8000)};
 const select=i=>{index=(i+cinemaSlides.length)%cinemaSlides.length;root.querySelectorAll('.cinema-frame').forEach((el,n)=>el.classList.toggle('is-current',n===index));root.querySelectorAll('[data-cinema-slide]').forEach(el=>{const active=Number(el.dataset.cinemaSlide)===index;el.classList.toggle('is-current',active);el.setAttribute('aria-current',String(active))});hero.dataset.slide=String(index)};
 const listen=(el,event,fn,options)=>{el?.addEventListener(event,fn,options);return()=>el?.removeEventListener(event,fn,options)};const cleanups=[];
 root.querySelectorAll('[data-cinema-slide]').forEach(button=>cleanups.push(listen(button,'click',()=>{select(Number(button.dataset.cinemaSlide));schedule()})));
 cleanups.push(listen(root.querySelector('.cinema-prev'),'click',()=>{select(index-1);schedule()}),listen(root.querySelector('.cinema-next'),'click',()=>{select(index+1);schedule()}));
 cleanups.push(listen(hero,'keydown',e=>{if(e.target.matches('input,button,a'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();select(index+(e.key==='ArrowRight'?1:-1));schedule()}}));
 cleanups.push(listen(hero,'pointerdown',e=>{if(!e.target.closest('a,button,input'))touchStart=e.clientX}),listen(hero,'pointerup',e=>{if(touchStart===null)return;const delta=e.clientX-touchStart;touchStart=null;if(Math.abs(delta)>55){select(index+(delta<0?1:-1));schedule()}}));
 cleanups.push(listen(motion,'click',()=>{paused=!paused;motion.textContent=paused?'▶':'Ⅱ';motion.setAttribute('aria-label',paused?'Reproduzir carrossel':'Pausar carrossel');hero.classList.toggle('motion-paused',paused);schedule()}));
 cleanups.push(listen(sound,'click',async()=>{if(audio.paused){try{await audio.play()}catch{notify('Toque novamente para ativar a trilha.')}}else audio.pause();paintSound()}));
 cleanups.push(listen(root.querySelector('#cinema-volume'),'input',e=>{audio.volume=Number(e.target.value)}),listen(audio,'pause',paintSound),listen(audio,'play',paintSound));
 const visibility=()=>{if(document.hidden){stop();audio.pause()}else schedule()};cleanups.push(listen(document,'visibilitychange',visibility));
 cleanups.push(listen(root.querySelector('#cinema-participate'),'click',participate));
 root.querySelectorAll('[data-cinema-tab]').forEach(button=>cleanups.push(listen(button,'click',()=>{const panel=root.querySelector('#cinema-editorial');panel.hidden=false;root.querySelectorAll('[data-cinema-tab]').forEach(b=>{b.classList.toggle('is-active',b===button);b.setAttribute('aria-pressed',String(b===button))});panel.innerHTML=editorial(button.dataset.cinemaTab)})));
 motion.textContent=paused?'▶':'Ⅱ';motion.setAttribute('aria-label',paused?'Reproduzir carrossel':'Pausar carrossel');hero.classList.toggle('motion-paused',paused);paintSound();select(0);schedule();return()=>{disposed=true;stop();audio.pause();cleanups.forEach(fn=>fn())};
}
function editorial(tab){if(tab==='episodios')return '<h2>HOCCO. — Parte 1</h2><p>Os episódios aparecerão aqui quando forem publicados.</p><a class="cinema-primary small" href="https://www.youtube.com/@hoccpov" target="_blank" rel="noopener noreferrer">Acompanhar no YouTube</a>';if(tab==='projetos')return '<h2>Projetos do reality</h2><p>As iniciativas documentadas na trajetória de Alex Hocc terão seus próprios registros aqui, conforme forem apresentadas. Empresas patrocinadoras ficam na área de ofertas.</p><a href="/ir-alem/">Conhecer quem financia a HOCCO →</a>';return '<h2>Você chegou no meio da história.</h2><p>HOCCO acompanha a trajetória de Alex Hocc: as origens, os projetos, as escolhas e as consequências. Uma série documental produzida em tempo real, sem um desfecho predeterminado.</p><p>A Parte 1 começa pelas memórias e pelos lugares que fazem parte dessa trajetória.</p><a href="#assistir">Conhecer a série →</a>'}
export function watchMarkup(tab='sinopse'){return `<section class="cinema-watch"><div class="cinema-watch-poster"><img src="/assets/cinema/school.webp" alt="Balanço com borboleta diante da escola CAIC"><span>Uma série original DOOX Studios</span></div><div class="cinema-watch-copy"><span class="cinema-coming">Em breve</span><h1>HOCCO<span>.</span></h1><p class="cinema-part">Parte 1</p><p class="cinema-tagline">Você chegou no meio da história.</p>${editorial(tab)}<div class="cinema-actions"><a class="cinema-primary" href="https://www.youtube.com/@hoccpov" target="_blank" rel="noopener noreferrer">${play}YouTube @hoccpov</a><a class="cinema-secondary" href="https://www.tiktok.com/@hoccpov" target="_blank" rel="noopener noreferrer">TikTok @hoccpov</a></div><p class="hint">Os botões abrem os canais oficiais. Nenhum episódio é anunciado como disponível antes da publicação.</p><a href="#inicio">← Voltar ao início</a></div></section>`}
export async function loadCinemaSponsors(root){const host=root.querySelector('#cinema-sponsor-content');if(!host)return;try{const d=await api('sponsor.catalog'),rows=d.active||[];if(!host.isConnected)return;let chosen={city:'',uf:''};try{chosen=JSON.parse(localStorage.getItem('hocco-city')||'{}')}catch{}const cities=[...new Set(rows.map(s=>s.city).filter(Boolean))];host.innerHTML=`<p class="hint">Cidade sugerida pela conexão. Você pode alterar livremente.</p><div class="cinema-location"><label for="cinema-city">Cidade</label><input id="cinema-city" maxlength="80" list="cinema-cities" placeholder="Todas as cidades" value="${esc(chosen.city||'')}"><datalist id="cinema-cities">${cities.map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist><label for="cinema-uf">UF</label><select id="cinema-uf"><option value="">Todas</option>${'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').map(uf=>`<option ${uf===chosen.uf?'selected':''}>${uf}</option>`).join('')}</select></div><div class="cinema-categories"><button class="is-active" data-home-category="">Todas</button>${[...new Set(rows.map(s=>s.category))].map(c=>`<button data-home-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="cinema-sponsor-grid" id="cinema-sponsor-grid"></div><p id="cinema-sponsor-result" class="hint" role="status"></p>`;let category='';const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const draw=()=>{const city=host.querySelector('#cinema-city').value.trim(),uf=host.querySelector('#cinema-uf').value;try{localStorage.setItem('hocco-city',JSON.stringify({city,uf}))}catch{}const visible=rows.filter(s=>(!city||norm(s.city)===norm(city))&&(!uf||s.state_code===uf)&&(!category||s.category===category));host.querySelector('#cinema-sponsor-grid').innerHTML=visible.length?visible.map(s=>`<a class="cinema-sponsor-card" href="/ir-alem/#empresa/${encodeURIComponent(s.id)}"><img src="${esc(s.cover_url||s.logo_url)}" alt="" loading="lazy" referrerpolicy="no-referrer"><div><small>${esc(s.category)} · ${esc(s.city||'Online')}</small><h3>${esc(s.company_name)}</h3><p>${esc(s.community_offer&&(!s.offer_expires_on||Date.parse(s.offer_expires_on+'T23:59:59-03:00')>Date.now())?s.community_offer:s.company_description||'Conheça esta marca parceira.')}</p><span>Ver empresa →</span></div></a>`).join(''):'<div class="cinema-sponsor-empty"><strong>Sua cidade também pode fazer parte.</strong><p>Ainda não há empresas nesta seleção. Conheça as marcas de outras cidades ou apresente sua empresa.</p><a class="cinema-secondary small" href="/ir-alem/#novo">Patrocinar a HOCCO →</a></div>';host.querySelector('#cinema-sponsor-result').textContent=visible.length?visible.length+' empresa(s) nesta seleção.':''};host.querySelector('#cinema-city').addEventListener('input',draw);host.querySelector('#cinema-uf').addEventListener('change',draw);host.querySelectorAll('[data-home-category]').forEach(button=>button.onclick=()=>{category=button.dataset.homeCategory;host.querySelectorAll('[data-home-category]').forEach(b=>b.classList.toggle('is-active',b===button));draw()});draw();suggestCity().then(choice=>{if(!choice?.city||!host.isConnected)return;const cityInput=host.querySelector('#cinema-city'),ufInput=host.querySelector('#cinema-uf');if(cityInput&&!cityInput.value&&document.activeElement!==cityInput){ufInput.value=choice.uf||'';cityInput.value=choice.city;cityInput.dispatchEvent(new Event('input',{bubbles:true}))}}).catch(()=>{})}catch{host.innerHTML='<p class="hint">As ofertas não puderam ser atualizadas agora.</p><a href="/ir-alem/">Consultar empresas →</a>'}}
